import numpy as np
from qiskit import QuantumCircuit

qasm="""OPENQASM 3.0;
include \"stdgates.inc\";
qubit[5] q;
bit[5] c;
h q[0];
h q[1];
h q[2];
h q[3];
h q[4];
// compute a=q0 xor q1 into q[1]
cx q[0], q[1];
// compute b=q3 xor q4 into q[4]
cx q[3], q[4];
// apply (-i)^a = s^3 on q[1]
s q[1];
s q[1];
s q[1];
// apply CZ between a(q[1]) and b(q[4])
h q[4];
cx q[1], q[4];
h q[4];
// uncompute
cx q[3], q[4];
cx q[0], q[1];
"""

qc=QuantumCircuit.from_qasm3_str(qasm)
